<script setup lang="ts">
const auth=useAdminApi(),rows=ref<any[]>([]),roles=ref<any[]>([]),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),q=ref(''),active=ref(''),page=ref(1),totalPages=ref(1),dialog=ref(false),roleDialog=ref(false),id=ref<number|null>(null),selected=ref<any>(null);
const form=reactive({name:'',email:'',password:'',is_admin:false,is_active:true});const roleIds=ref<number[]>([]);
function extract(r:any){return r?.data?.data||r?.data||[];}function pages(r:any){return Number(r?.data?.last_page||r?.last_page||1);}function message(e:any){const errors=e?.data?.errors;return errors?Object.values(errors).flat().join(' · '):e?.data?.message||'عملیات انجام نشد.';}
async function load(){loading.value=true;error.value='';try{const params=new URLSearchParams({page:String(page.value),per_page:'20'});if(q.value.trim())params.set('q',q.value.trim());if(active.value!=='')params.set('is_active',active.value);const r:any=await auth.request(`/admin/users?${params}`);rows.value=extract(r);totalPages.value=pages(r);if(auth.user.value?.is_admin){const rr:any=await auth.request('/admin/roles');roles.value=extract(rr);}}catch(e:any){error.value=message(e);}finally{loading.value=false;}}
function add(){id.value=null;Object.assign(form,{name:'',email:'',password:'',is_admin:false,is_active:true});dialog.value=true;}
function edit(row:any){id.value=row.id;Object.assign(form,{name:row.name,email:row.email,password:'',is_admin:row.is_admin,is_active:row.is_active!==false});dialog.value=true;}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const body:any={...form};if(id.value&&!body.password)delete body.password;await auth.request(`/admin/users${id.value?`/${id.value}`:''}`,{method:id.value?'PATCH':'POST',body});dialog.value=false;success.value='اطلاعات کاربر ذخیره شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function assignRoles(row:any){selected.value=row;busy.value=true;error.value='';try{const r:any=await auth.request(`/admin/users/${row.id}/roles`);roleIds.value=extract(r).map((x:any)=>Number(x.id));roleDialog.value=true;}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function saveRoles(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await auth.request(`/admin/users/${selected.value.id}/roles`,{method:'PUT',body:{role_ids:roleIds.value}});roleDialog.value=false;success.value='نقش‌های کاربر ذخیره شدند. نشست‌های قبلی این کاربر باطل شده‌اند.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function remove(row:any){if(!confirm(`کاربر «${row.name}» حذف شود؟`))return;busy.value=true;try{await auth.request(`/admin/users/${row.id}`,{method:'DELETE'});success.value='کاربر حذف شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
let searchTimer:ReturnType<typeof setTimeout>|undefined;function searchDebounce(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load();},300);}onBeforeUnmount(()=>clearTimeout(searchTimer));watch([page,active],load);onMounted(load);
</script>
<template><main dir="rtl" class="admin-page"><header class="admin-page__header"><div><div class="admin-eyebrow">دسترسی و حساب‌ها</div><h1>مدیریت کاربران</h1><p>تخصیص نقش و ارتقای دسترسی فقط در اختیار Super Admin است.</p></div><v-btn v-if="auth.user.value?.is_admin" color="primary" prepend-icon="mdi-plus" @click="add">کاربر جدید</v-btn></header>
<v-alert v-if="error" type="error" variant="tonal" class="mb-3" closable @click:close="error=''">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-3" closable @click:close="success=''">{{success}}</v-alert>
<v-row><v-col cols="12" md="8"><v-text-field v-model="q" label="جست‌وجوی نام، ایمیل یا تلفن" clearable @update:model-value="searchDebounce" @keyup.enter="load"/></v-col><v-col cols="12" md="4"><v-select v-model="active" :items="[{title:'همه وضعیت‌ها',value:''},{title:'فعال',value:'1'},{title:'غیرفعال',value:'0'}]" label="وضعیت"/></v-col></v-row>
<v-card class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>نام</th><th>ایمیل</th><th>نقش‌ها</th><th>وضعیت</th><th>ایجاد</th><th>عملیات</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.name}}</td><td>{{row.email}}</td><td>{{row.is_admin?'Super Admin':(row.roles||[]).map((x:any)=>x.label).join('، ')||'بدون نقش'}}</td><td>{{row.is_active?'فعال':'غیرفعال'}}</td><td>{{row.created_at||'—'}}</td><td class="text-no-wrap"><v-btn size="small" variant="text" @click="edit(row)">ویرایش</v-btn><v-btn v-if="auth.user.value?.is_admin" size="small" variant="text" @click="assignRoles(row)">نقش‌ها</v-btn><v-btn v-if="auth.user.value?.is_admin" size="small" color="error" variant="text" @click="remove(row)">حذف</v-btn></td></tr><tr v-if="!loading&&!rows.length"><td colspan="6"><div class="admin-empty-state">کاربری یافت نشد.</div></td></tr></tbody></v-table></div><v-progress-linear v-if="loading" indeterminate/><div v-if="totalPages>1" class="admin-table-pagination"><v-btn :disabled="page<=1" @click="page--">قبلی</v-btn><span>صفحه {{page}} از {{totalPages}}</span><v-btn :disabled="page>=totalPages" @click="page++">بعدی</v-btn></div></v-card>
<v-dialog v-model="dialog" max-width="600"><v-card class="pa-5" dir="rtl"><h2 class="mb-4">{{id?'ویرایش کاربر':'ایجاد کاربر'}}</h2><v-text-field v-model="form.name" label="نام"/><v-text-field v-model="form.email" type="email" label="ایمیل"/><v-text-field v-model="form.password" type="password" :label="id?'رمز جدید (اختیاری)':'رمز عبور (حداقل ۱۲ نویسه)'"/><v-switch v-if="auth.user.value?.is_admin" v-model="form.is_admin" label="Super Admin"/><v-switch v-model="form.is_active" label="حساب فعال"/><v-alert type="info" variant="tonal" class="mb-3">تغییر سطح دسترسی یا غیرفعال‌سازی، نشست‌های جاری کاربر را از backend باطل می‌کند.</v-alert><div class="d-flex ga-2"><v-btn color="primary" :loading="busy" :disabled="!form.name||!form.email||(!id&&form.password.length<12)" @click="save">ذخیره</v-btn><v-btn variant="text" @click="dialog=false">انصراف</v-btn></div></v-card></v-dialog>
<v-dialog v-model="roleDialog" max-width="650"><v-card class="pa-5" dir="rtl"><h2 class="mb-2">نقش‌های {{selected?.name}}</h2><v-alert type="warning" variant="tonal" class="mb-3">با ذخیره، tokenهای کاربر باطل می‌شوند و باید دوباره وارد شود.</v-alert><v-select v-model="roleIds" :items="roles.filter((r:any)=>r.is_assignable)" item-title="label" item-value="id" label="نقش‌های قابل تخصیص" multiple chips/><div class="d-flex ga-2"><v-btn color="primary" :loading="busy" @click="saveRoles">ذخیره نقش‌ها</v-btn><v-btn variant="text" @click="roleDialog=false">انصراف</v-btn></div></v-card></v-dialog></main></template>
